insert into public.lesson_signs(sign_id,category_id,shape,title_en,title_ml,rule_en,rule_ml,display_order) values ('info_16','informatory','Rectangular','Workshop','വർക്ക്ഷോപ്പ്','A vehicle repair workshop is available nearby.','സമീപത്ത് വാഹന റിപ്പയർ വർക്ക്ഷോപ്പ് ലഭ്യമാണ്.',65) on conflict (sign_id) do update set category_id=excluded.category_id,shape=excluded.shape,title_en=excluded.title_en,title_ml=excluded.title_ml,rule_en=excluded.rule_en,rule_ml=excluded.rule_ml,display_order=excluded.display_order;
