insert into public.lesson_signs(sign_id,category_id,shape,title_en,title_ml,rule_en,rule_ml,display_order) values ('police_01','trafficpolice','Police Hand Signal','Stop','നിർത്തുക','Right arm raised vertically with palm forward.','പോലീസ് ഉദ്യോഗസ്ഥന്റെ കൈസിഗ്നൽ ശ്രദ്ധിച്ച് അതനുസരിച്ച് വാഹനം നിയന്ത്രിക്കുക.',80) on conflict (sign_id) do update set category_id=excluded.category_id,shape=excluded.shape,title_en=excluded.title_en,title_ml=excluded.title_ml,rule_en=excluded.rule_en,rule_ml=excluded.rule_ml,display_order=excluded.display_order;
insert into public.lesson_signs(sign_id,category_id,shape,title_en,title_ml,rule_en,rule_ml,display_order) values ('police_02','trafficpolice','Police Hand Signal','Move Forward','മുന്നോട്ട് പോകുക','Right arm moved up and down to invite traffic forward.','പോലീസ് ഉദ്യോഗസ്ഥന്റെ കൈസിഗ്നൽ ശ്രദ്ധിച്ച് അതനുസരിച്ച് വാഹനം നിയന്ത്രിക്കുക.',81) on conflict (sign_id) do update set category_id=excluded.category_id,shape=excluded.shape,title_en=excluded.title_en,title_ml=excluded.title_ml,rule_en=excluded.rule_en,rule_ml=excluded.rule_ml,display_order=excluded.display_order;
insert into public.lesson_signs(sign_id,category_id,shape,title_en,title_ml,rule_en,rule_ml,display_order) values ('police_03','trafficpolice','Police Hand Signal','Slow Down','വേഗത കുറയ്ക്കുക','Right arm moved horizontally with palm down.','പോലീസ് ഉദ്യോഗസ്ഥന്റെ കൈസിഗ്നൽ ശ്രദ്ധിച്ച് അതനുസരിച്ച് വാഹനം നിയന്ത്രിക്കുക.',82) on conflict (sign_id) do update set category_id=excluded.category_id,shape=excluded.shape,title_en=excluded.title_en,title_ml=excluded.title_ml,rule_en=excluded.rule_en,rule_ml=excluded.rule_ml,display_order=excluded.display_order;
insert into public.lesson_signs(sign_id,category_id,shape,title_en,title_ml,rule_en,rule_ml,display_order) values ('police_04','trafficpolice','Police Hand Signal','Turn Left','ഇടത്തോട്ട് തിരിയുക','Right arm horizontal and moved from right to left.','പോലീസ് ഉദ്യോഗസ്ഥന്റെ കൈസിഗ്നൽ ശ്രദ്ധിച്ച് അതനുസരിച്ച് വാഹനം നിയന്ത്രിക്കുക.',83) on conflict (sign_id) do update set category_id=excluded.category_id,shape=excluded.shape,title_en=excluded.title_en,title_ml=excluded.title_ml,rule_en=excluded.rule_en,rule_ml=excluded.rule_ml,display_order=excluded.display_order;
insert into public.lesson_signs(sign_id,category_id,shape,title_en,title_ml,rule_en,rule_ml,display_order) values ('police_05','trafficpolice','Police Hand Signal','Turn Right','വലത്തോട്ട് തിരിയുക','Right arm horizontal and moved from left to right.','പോലീസ് ഉദ്യോഗസ്ഥന്റെ കൈസിഗ്നൽ ശ്രദ്ധിച്ച് അതനുസരിച്ച് വാഹനം നിയന്ത്രിക്കുക.',84) on conflict (sign_id) do update set category_id=excluded.category_id,shape=excluded.shape,title_en=excluded.title_en,title_ml=excluded.title_ml,rule_en=excluded.rule_en,rule_ml=excluded.rule_ml,display_order=excluded.display_order;
