insert into public.lesson_signs(sign_id,category_id,shape,title_en,title_ml,rule_en,rule_ml,display_order) values ('driver_01','driverhand','Driver Hand Signal','Intend to Move Left','ഇടത്തോട്ട് പോകാനുള്ള സൂചന','Arm signal indicating an intention to move left.','ഡ്രൈവർ കൈസിഗ്നൽ വ്യക്തമായി നൽകി മറ്റ് റോഡ് ഉപയോക്താക്കൾക്ക് ഉദ്ദേശ്യം അറിയിക്കുക.',90) on conflict (sign_id) do update set category_id=excluded.category_id,shape=excluded.shape,title_en=excluded.title_en,title_ml=excluded.title_ml,rule_en=excluded.rule_en,rule_ml=excluded.rule_ml,display_order=excluded.display_order;
