insert into public.lesson_signs(sign_id,category_id,shape,title_en,title_ml,rule_en,rule_ml,display_order) values ('driver_05','driverhand','Driver Hand Signal','Indicating Overtaking','ഓവർടേക്ക് ചെയ്യാനുള്ള സൂചന','Arm signal indicating that the vehicle is about to overtake.','ഡ്രൈവർ കൈസിഗ്നൽ വ്യക്തമായി നൽകി മറ്റ് റോഡ് ഉപയോക്താക്കൾക്ക് ഉദ്ദേശ്യം അറിയിക്കുക.',94) on conflict (sign_id) do update set category_id=excluded.category_id,shape=excluded.shape,title_en=excluded.title_en,title_ml=excluded.title_ml,rule_en=excluded.rule_en,rule_ml=excluded.rule_ml,display_order=excluded.display_order;
insert into public.lesson_signs(sign_id,category_id,shape,title_en,title_ml,rule_en,rule_ml,display_order) values ('rm_05','roadmarking','Road Marking','Edge Line (White)','വെള്ള അരികുരേഖ','Follow the road marking and associated traffic control.','വെള്ള അരികുരേഖ കാണുന്നിടത്ത് ബന്ധപ്പെട്ട റോഡ് നിയന്ത്രണം പാലിക്കുക.',54) on conflict (sign_id) do update set category_id=excluded.category_id,shape=excluded.shape,title_en=excluded.title_en,title_ml=excluded.title_ml,rule_en=excluded.rule_en,rule_ml=excluded.rule_ml,display_order=excluded.display_order;
insert into public.lesson_signs(sign_id,category_id,shape,title_en,title_ml,rule_en,rule_ml,display_order) values ('rm_06','roadmarking','Road Marking','No Overtaking Double White Line','ഓവർടേക്ക് പാടില്ലാത്ത ഇരട്ട വെള്ളരേഖ','Follow the road marking and associated traffic control.','ഓവർടേക്ക് പാടില്ലാത്ത ഇരട്ട വെള്ളരേഖ കാണുന്നിടത്ത് ബന്ധപ്പെട്ട റോഡ് നിയന്ത്രണം പാലിക്കുക.',55) on conflict (sign_id) do update set category_id=excluded.category_id,shape=excluded.shape,title_en=excluded.title_en,title_ml=excluded.title_ml,rule_en=excluded.rule_en,rule_ml=excluded.rule_ml,display_order=excluded.display_order;
insert into public.lesson_signs(sign_id,category_id,shape,title_en,title_ml,rule_en,rule_ml,display_order) values ('rm_07','roadmarking','Road Marking','Give Way Line (Broken White)','വഴി കൊടുക്കേണ്ട തകർന്ന വെള്ളരേഖ','Follow the road marking and associated traffic control.','വഴി കൊടുക്കേണ്ട തകർന്ന വെള്ളരേഖ കാണുന്നിടത്ത് ബന്ധപ്പെട്ട റോഡ് നിയന്ത്രണം പാലിക്കുക.',56) on conflict (sign_id) do update set category_id=excluded.category_id,shape=excluded.shape,title_en=excluded.title_en,title_ml=excluded.title_ml,rule_en=excluded.rule_en,rule_ml=excluded.rule_ml,display_order=excluded.display_order;
